parameterdescription.para:
公開鍵を保存するバッファへのポインタ Example DhKeykey;
intret;
bytepriv[256];
bytepub[256];
word32privSz,pubSz;

wc_InitDhKey(&key);//initializekey
//SetDHparametersusingwc_DhSetKeyorwc_DhKeyDecode
WC_RNGrng;
wc_InitRng(&rng);//initializerng
ret=wc_DhGenerateKeyPair(&key,&rng,priv,&privSz,pub,&pubSz);

受信した公開鍵を含むバッファへのポインタ Example DhKeykey;
intret;
bytepriv[256];
byteagree[256];
word32agreeSz;

//initializekey,setkeyprimeandbase
//wc_DhGenerateKeyPair--storeprivatekeyinpriv
bytepub[]={//initializedwiththereceivedpublickey};
ret=wc_DhAgree(&key,agree,&agreeSz,priv,sizeof(priv),pub,
sizeof(pub));
if(ret!=0){
//errorgeneratingsharedkey
}

入力キーで初期化するためのDHKEY構造体へのポインタ Example DhKeykey;
word32idx=0;

bytekeyBuff[1024];
//initializewithDERformattedkey
wc_DhKeyInit(&key);
ret=wc_DhKeyDecode(keyBuff,&idx,&key,sizeof(keyBuff));

if(ret!=0){
//errordecodingkey
}

キーで使用するためのベースを含むバッファへのポインタ Example DhKeykey;

bytep[]={//initializewithprime};
byteg[]={//initializewithbase};
wc_DhKeyInit(&key);
ret=wc_DhSetKey(key,p,sizeof(p),g,sizeof(g));

if(ret!=0){
//errorsettingkey
}

解析されたベースを保存するバッファへのポインタ Example bytedhCert[]={initializewithDERformattedcertificate};
bytep[MAX_DH_SIZE];
byteg[MAX_DH_SIZE];
word32pSz=MAX_DH_SIZE;
word32gSz=MAX_DH_SIZE;

ret=wc_DhParamsLoad(dhCert,sizeof(dhCert),p,&pSz,g,&gSz);
if(ret!=0){
//errorparsinginputs
}
